    #pragma clang attribute pop
  #elif RCRE_NEED_POP_AVX512 == 1
    #pragma GCC pop_options
  #endif
  #undef RCRE_NEED_POP_AVX512
#endif

#endif /* (__x86_64__ || _M_X64) && AVX512F-capable compiler */

