/**
 * @file kernels_wasm.c
 * @brief WebAssembly 128-bit SIMD Micro-Kernels
 * 
 * Satisfies HAL-REQ-03.
 * Targets modern browsers with WASM SIMD enabled.
 */


#if defined(__wasm_simd128__)
#include <wasm_simd128.h>

float rcre_wasm_dot_f32(const float* x, const float* y, size_t n) {
    v128_t sum0 = wasm_f32x4_splat(0.0f);
    v128_t sum1 = wasm_f32x4_splat(0.0f);

    size_t i = 0;
    for (; i + 7 < n; i += 8) {
        v128_t x0 = wasm_v128_load(&x[i + 0]);
        v128_t y0 = wasm_v128_load(&y[i + 0]);
        sum0 = wasm_f32x4_add(sum0, wasm_f32x4_mul(x0, y0));

        v128_t x1 = wasm_v128_load(&x[i + 4]);
        v128_t y1 = wasm_v128_load(&y[i + 4]);
        sum1 = wasm_f32x4_add(sum1, wasm_f32x4_mul(x1, y1));
    }

    v128_t sum = wasm_f32x4_add(sum0, sum1);
    float total = wasm_f32x4_extract_lane(sum, 0) +
                  wasm_f32x4_extract_lane(sum, 1) +
                  wasm_f32x4_extract_lane(sum, 2) +
                  wasm_f32x4_extract_lane(sum, 3);

    for (; i < n; ++i) {
        total += x[i] * y[i];
    }
    return total;
}

void rcre_wasm_axpy_f32(size_t n, float alpha, const float* x, float* y) {
    v128_t a_vec = wasm_f32x4_splat(alpha);

    size_t i = 0;
    for (; i + 7 < n; i += 8) {
        v128_t x0 = wasm_v128_load(&x[i + 0]);
        v128_t y0 = wasm_v128_load(&y[i + 0]);
        wasm_v128_store(&y[i + 0], wasm_f32x4_add(y0, wasm_f32x4_mul(a_vec, x0)));

        v128_t x1 = wasm_v128_load(&x[i + 4]);
        v128_t y1 = wasm_v128_load(&y[i + 4]);
        wasm_v128_store(&y[i + 4], wasm_f32x4_add(y1, wasm_f32x4_mul(a_vec, x1)));
    }

    for (; i < n; ++i) {
        y[i] += alpha * x[i];
    }
}

/* 4x8 register-blocked GEMM micro-kernel on WebAssembly 128-bit SIMD */
static void wasm_gemm_microkernel_4x8(size_t K, float alpha,
                                      const float* A, size_t lda,
                                      const float* B, size_t ldb,
                                      float beta, float* C, size_t ldc) {
    v128_t c00 = wasm_f32x4_splat(0.0f);
    v128_t c01 = wasm_f32x4_splat(0.0f);
    v128_t c10 = wasm_f32x4_splat(0.0f);
    v128_t c11 = wasm_f32x4_splat(0.0f);
    v128_t c20 = wasm_f32x4_splat(0.0f);
    v128_t c21 = wasm_f32x4_splat(0.0f);
    v128_t c30 = wasm_f32x4_splat(0.0f);
    v128_t c31 = wasm_f32x4_splat(0.0f);

    for (size_t k = 0; k < K; ++k) {
        v128_t b0 = wasm_v128_load(&B[k * ldb + 0]);
        v128_t b1 = wasm_v128_load(&B[k * ldb + 4]);

        v128_t a0 = wasm_f32x4_splat(A[0 * lda + k]);
        c00 = wasm_f32x4_add(c00, wasm_f32x4_mul(b0, a0));
        c01 = wasm_f32x4_add(c01, wasm_f32x4_mul(b1, a0));

        v128_t a1 = wasm_f32x4_splat(A[1 * lda + k]);
        c10 = wasm_f32x4_add(c10, wasm_f32x4_mul(b0, a1));
        c11 = wasm_f32x4_add(c11, wasm_f32x4_mul(b1, a1));

        v128_t a2 = wasm_f32x4_splat(A[2 * lda + k]);
        c20 = wasm_f32x4_add(c20, wasm_f32x4_mul(b0, a2));
        c21 = wasm_f32x4_add(c21, wasm_f32x4_mul(b1, a2));

        v128_t a3 = wasm_f32x4_splat(A[3 * lda + k]);
        c30 = wasm_f32x4_add(c30, wasm_f32x4_mul(b0, a3));
        c31 = wasm_f32x4_add(c31, wasm_f32x4_mul(b1, a3));
    }

    v128_t a_vec = wasm_f32x4_splat(alpha);
    v128_t b_vec = wasm_f32x4_splat(beta);

    #define STORE_ROW_WASM(row, acc0, acc1) do { \
        v128_t old0 = (beta == 0.0f) ? wasm_f32x4_splat(0.0f) : wasm_v128_load(&C[(row) * ldc + 0]); \
        v128_t old1 = (beta == 0.0f) ? wasm_f32x4_splat(0.0f) : wasm_v128_load(&C[(row) * ldc + 4]); \
        v128_t out0 = wasm_f32x4_add(wasm_f32x4_mul(old0, b_vec), wasm_f32x4_mul(acc0, a_vec)); \
        v128_t out1 = wasm_f32x4_add(wasm_f32x4_mul(old1, b_vec), wasm_f32x4_mul(acc1, a_vec)); \
        wasm_v128_store(&C[(row) * ldc + 0], out0); \
        wasm_v128_store(&C[(row) * ldc + 4], out1); \
    } while(0)

    STORE_ROW_WASM(0, c00, c01);
    STORE_ROW_WASM(1, c10, c11);
    STORE_ROW_WASM(2, c20, c21);
    STORE_ROW_WASM(3, c30, c31);
    #undef STORE_ROW_WASM
}

void rcre_wasm_gemm_f32(size_t M, size_t N, size_t K, float alpha, 
                        const float* A, size_t lda, 
                        const float* B, size_t ldb, 
                        float beta, float* C, size_t ldc) {
    /* Cache-blocked driver for 4x8 micro-kernel */
    const size_t MB = 64;
    const size_t NB = 64;
    const size_t KB = 64;

    /* Initialize C with beta scaling if needed */
    if (beta != 1.0f) {
        for (size_t i = 0; i < M; ++i) {
            for (size_t j = 0; j < N; ++j) {
                C[i * ldc + j] = (beta == 0.0f) ? 0.0f : C[i * ldc + j] * beta;
            }
        }
    }

    if (alpha == 0.0f) return;

    for (size_t ii = 0; ii < M; ii += MB) {
        size_t i_end = (ii + MB < M) ? ii + MB : M;

        for (size_t jj = 0; jj < N; jj += NB) {
            size_t j_end = (jj + NB < N) ? jj + NB : N;

            for (size_t kk = 0; kk < K; kk += KB) {
                size_t k_end = (kk + KB < K) ? kk + KB : K;
                size_t sub_K = k_end - kk;

                /* 4x8 tiled blocks */
                size_t i = ii;
                for (; i + 3 < i_end; i += 4) {
                    size_t j = jj;
                    for (; j + 7 < j_end; j += 8) {
                        wasm_gemm_microkernel_4x8(sub_K, alpha,
                                                  &A[i * lda + kk], lda,
                                                  &B[kk * ldb + j], ldb,
                                                  1.0f, /* C already pre-scaled by beta */
                                                  &C[i * ldc + j], ldc);
                    }
                    /* Remainder columns in 4-row block */
                    for (; j < j_end; ++j) {
                        for (size_t r = 0; r < 4; ++r) {
                            float acc = 0.0f;
                            for (size_t k = kk; k < k_end; ++k) {
                                acc += A[(i + r) * lda + k] * B[k * ldb + j];
                            }
                            C[(i + r) * ldc + j] += alpha * acc;
                        }
                    }
                }

                /* Remainder rows */
                for (; i < i_end; ++i) {
                    for (size_t j = jj; j < j_end; ++j) {
                        float acc = 0.0f;
                        for (size_t k = kk; k < k_end; ++k) {
                            acc += A[i * lda + k] * B[k * ldb + j];
                        }
                        C[i * ldc + j] += alpha * acc;
                    }
                }
            }
        }
    }
}

void rcre_wasm_rgb_to_gray_u8(const uint8_t* rgb, uint8_t* gray, size_t num_pixels) {
    const v128_t r_coeff = wasm_i32x4_splat(9798);
    const v128_t g_coeff = wasm_i32x4_splat(19235);
    const v128_t b_coeff = wasm_i32x4_splat(3735);
    const v128_t bias    = wasm_i32x4_splat(16384);

    size_t i = 0;
    for (; i + 7 < num_pixels; i += 8) {
        v128_t r32_0 = wasm_i32x4_make(rgb[(i + 0) * 3 + 0], rgb[(i + 1) * 3 + 0], rgb[(i + 2) * 3 + 0], rgb[(i + 3) * 3 + 0]);
        v128_t g32_0 = wasm_i32x4_make(rgb[(i + 0) * 3 + 1], rgb[(i + 1) * 3 + 1], rgb[(i + 2) * 3 + 1], rgb[(i + 3) * 3 + 1]);
        v128_t b32_0 = wasm_i32x4_make(rgb[(i + 0) * 3 + 2], rgb[(i + 1) * 3 + 2], rgb[(i + 2) * 3 + 2], rgb[(i + 3) * 3 + 2]);

        v128_t r32_1 = wasm_i32x4_make(rgb[(i + 4) * 3 + 0], rgb[(i + 5) * 3 + 0], rgb[(i + 6) * 3 + 0], rgb[(i + 7) * 3 + 0]);
        v128_t g32_1 = wasm_i32x4_make(rgb[(i + 4) * 3 + 1], rgb[(i + 5) * 3 + 1], rgb[(i + 6) * 3 + 1], rgb[(i + 7) * 3 + 1]);
        v128_t b32_1 = wasm_i32x4_make(rgb[(i + 4) * 3 + 2], rgb[(i + 5) * 3 + 2], rgb[(i + 6) * 3 + 2], rgb[(i + 7) * 3 + 2]);

        v128_t acc0 = bias;
        acc0 = wasm_i32x4_add(acc0, wasm_i32x4_mul(r32_0, r_coeff));
        acc0 = wasm_i32x4_add(acc0, wasm_i32x4_mul(g32_0, g_coeff));
        acc0 = wasm_i32x4_add(acc0, wasm_i32x4_mul(b32_0, b_coeff));
        v128_t gray32_0 = wasm_u32x4_shr(acc0, 15);

        v128_t acc1 = bias;
        acc1 = wasm_i32x4_add(acc1, wasm_i32x4_mul(r32_1, r_coeff));
        acc1 = wasm_i32x4_add(acc1, wasm_i32x4_mul(g32_1, g_coeff));
        acc1 = wasm_i32x4_add(acc1, wasm_i32x4_mul(b32_1, b_coeff));
        v128_t gray32_1 = wasm_u32x4_shr(acc1, 15);

        v128_t gray16 = wasm_i16x8_narrow_i32x4(gray32_0, gray32_1);
        v128_t gray8  = wasm_u8x16_narrow_i16x8(gray16, gray16);

        uint64_t res8 = (uint64_t)(uint32_t)wasm_i32x4_extract_lane(gray8, 0) |
                        ((uint64_t)(uint32_t)wasm_i32x4_extract_lane(gray8, 1) << 32);
        __builtin_memcpy(&gray[i], &res8, 8);
    }

    /* Scalar remainder */
    for (; i < num_pixels; ++i) {
        uint32_t r = rgb[i * 3 + 0];
        uint32_t g = rgb[i * 3 + 1];
        uint32_t b = rgb[i * 3 + 2];
        gray[i] = (uint8_t)((9798 * r + 19235 * g + 3735 * b + 16384) >> 15);
    }
}

size_t rcre_wasm_find_byte(const uint8_t* hay, size_t len, uint8_t needle) {
    if (!hay || len == 0) {
        return RCRE_NPOS;
    }

    const v128_t vn = wasm_i8x16_splat((int8_t)needle);
    size_t i = 0;

    for (; i + 15 < len; i += 16) {
        uint32_t m = (uint32_t)wasm_i8x16_bitmask(wasm_i8x16_eq(wasm_v128_load(&hay[i]), vn));
        if (m != 0) {
            return i + (size_t)__builtin_ctz(m);
        }
    }

    for (; i < len; ++i) {
        if (hay[i] == needle) return i;
    }
    return RCRE_NPOS;
}

size_t rcre_wasm_count_byte(const uint8_t* hay, size_t len, uint8_t needle) {
    if (!hay || len == 0) {
        return 0;
    }

    const v128_t vn = wasm_i8x16_splat((int8_t)needle);
    size_t total = 0;
    size_t i = 0;

    while (i + 15 < len) {
        v128_t acc = wasm_i8x16_splat(0);
        size_t block_iters = (len - i) / 16;
        if (block_iters > 255) {
            block_iters = 255;
        }
        for (size_t b = 0; b < block_iters; ++b, i += 16) {
            acc = wasm_i8x16_sub(acc, wasm_i8x16_eq(wasm_v128_load(&hay[i]), vn));
        }
        v128_t s16 = wasm_u16x8_extadd_pairwise_u8x16(acc);
        v128_t s32 = wasm_u32x4_extadd_pairwise_u16x8(s16);
        total += (size_t)wasm_u32x4_extract_lane(s32, 0) +
                 (size_t)wasm_u32x4_extract_lane(s32, 1) +
                 (size_t)wasm_u32x4_extract_lane(s32, 2) +
                 (size_t)wasm_u32x4_extract_lane(s32, 3);
    }

    for (; i < len; ++i) {
        total += (size_t)(hay[i] == needle);
    }
    return total;
}

void rcre_wasm_gemv_f32(size_t M, size_t K, float alpha,
                        const float* A, size_t lda,
                        const float* x, float beta, float* y) {
    for (size_t i = 0; i < M; ++i) {
        float acc = rcre_wasm_dot_f32(&A[i * lda], x, K);
        float prev = (beta == 0.0f) ? 0.0f : (y[i] * beta);
        y[i] = prev + alpha * acc;
    }
}

#endif /* __wasm_simd128__ */

/* --- Source: cpu_probe.c --- */
/**
 * @file cpu_probe.c
 * @brief Dynamic Runtime CPU Capability & SIMD ISA Probing
 * 
 * Satisfies HAL-REQ-01.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>
#include <unistd.h>

#if defined(__APPLE__)
#include <sys/sysctl.h>
#elif defined(__linux__) && (defined(__x86_64__) || defined(_M_X64) || defined(__i386__))
#include <cpuid.h>
#endif

static atomic_bool s_probed = false;
static uint32_t s_features = 0;
static char s_brand[128] = "Unknown CPU";
static RCRE_CpuTopology s_topology = { 1, 1, 0, 1, 0 };

static uint32_t probe_env_positive_u32(const char* name) {
    const char* v = getenv(name);
    if (!v || v[0] == '\0') return 0;
    char* end = nullptr;
    unsigned long parsed = strtoul(v, &end, 10);
    if (end == v || parsed == 0 || parsed > 65535UL) return 0;
    return (uint32_t)parsed;
}

#if defined(__linux__)
static uint32_t probe_linux_cgroup_quota_cores(uint32_t host_cores) {
    /* cgroup v2: /sys/fs/cgroup/cpu.max format: "<quota_us> <period_us>" or "max 100000" */
    FILE* f = fopen("/sys/fs/cgroup/cpu.max", "r");
    if (f) {
        char quota_tok[32] = {0};
        unsigned long long period = 0;
        if (fscanf(f, "%31s %llu", quota_tok, &period) == 2 && period > 0) {
            if (strcmp(quota_tok, "max") != 0) {
                unsigned long long quota = strtoull(quota_tok, nullptr, 10);
                if (quota > 0) {
                    fclose(f);
                    uint32_t c = (uint32_t)((quota + period - 1ULL) / period);
                    if (c == 0) c = 1;
                    return (c < host_cores) ? c : host_cores;
                }
            }
        }
        fclose(f);
    }
    return host_cores;
}
#endif

static void probe_topology(void) {
    uint32_t logical = 1;
#if defined(_SC_NPROCESSORS_ONLN)
    long nprocs = sysconf(_SC_NPROCESSORS_ONLN);
    if (nprocs > 0) logical = (uint32_t)nprocs;
#endif

    uint32_t perf = logical;
    uint32_t eff  = 0;
    uint32_t quota = logical;
    uint64_t ram_bytes = 0;

#if defined(__APPLE__)
    int p_val = 0, e_val = 0;
    size_t sz_p = sizeof(p_val), sz_e = sizeof(e_val);
    if (sysctlbyname("hw.perflevel0.physicalcpu", &p_val, &sz_p, nullptr, 0) == 0 && p_val > 0) {
        perf = (uint32_t)p_val;
        if (sysctlbyname("hw.perflevel1.physicalcpu", &e_val, &sz_e, nullptr, 0) == 0 && e_val >= 0) {
            eff = (uint32_t)e_val;
        }
    }
    uint64_t mem64 = 0;
    size_t sz_mem = sizeof(mem64);
    if (sysctlbyname("hw.memsize", &mem64, &sz_mem, nullptr, 0) == 0) {
        ram_bytes = mem64;
    }
#elif defined(__linux__)
    quota = probe_linux_cgroup_quota_cores(logical);
    long pages = sysconf(_SC_PHYS_PAGES);
    long page_sz = sysconf(_SC_PAGESIZE);
    if (pages > 0 && page_sz > 0) {
        ram_bytes = (uint64_t)pages * (uint64_t)page_sz;
    }
#endif

    /* Respect HPC scheduler per-allocation limits if narrower than cgroup/host */
    uint32_t slurm_cpus = probe_env_positive_u32("SLURM_CPUS_ON_NODE");
    if (slurm_cpus == 0) {
        slurm_cpus = probe_env_positive_u32("SLURM_CPUS_PER_TASK");
    }
    if (slurm_cpus > 0 && slurm_cpus < quota) {
        quota = slurm_cpus;
    }

    s_topology.logical_cores         = logical;
    s_topology.perf_cores            = perf;
    s_topology.eff_cores             = eff;
    s_topology.effective_quota_cores = (quota > 0) ? quota : 1;
    s_topology.total_ram_bytes       = ram_bytes;
}

static void probe_cpu(void) {
    uint32_t feats = RCRE_CPU_FEAT_SCALAR;

#if defined(__ARM_NEON) || defined(__aarch64__) || defined(_M_ARM64)
    feats |= RCRE_CPU_FEAT_NEON;
#endif
#if defined(__ARM_FEATURE_DOTPROD)
    feats |= RCRE_CPU_FEAT_ARM_DOTPROD;
#endif
#if defined(__ARM_FEATURE_SVE2)
    feats |= RCRE_CPU_FEAT_ARM_SVE2;
#endif

#if defined(__wasm_simd128__)
    feats |= RCRE_CPU_FEAT_WASM_SIMD;
#endif

#if defined(__APPLE__)
    size_t len = sizeof(s_brand);
    if (sysctlbyname("machdep.cpu.brand_string", s_brand, &len, NULL, 0) != 0) {
        strncpy(s_brand, "Apple Silicon", sizeof(s_brand) - 1);
    }
#elif (defined(__x86_64__) || defined(_M_X64) || defined(__i386__)) && !defined(_MSC_VER)
    /* x86 CPUID feature detection */
    unsigned int eax, ebx, ecx, edx;
    if (__get_cpuid(1, &eax, &ebx, &ecx, &edx)) {
        if (ecx & (1 << 12)) {
            feats |= RCRE_CPU_FEAT_FMA;
        }
    }
    if (__get_cpuid_count(7, 0, &eax, &ebx, &ecx, &edx)) {
        if (ebx & (1 << 5)) {
            feats |= RCRE_CPU_FEAT_AVX2;
        }
        if (ebx & (1 << 16)) {
            feats |= RCRE_CPU_FEAT_AVX512F;
        }
    }

    /* Probe brand string via extended cpuid leaves */
    unsigned int brand_regs[12];
    if (__get_cpuid(0x80000000, &eax, &ebx, &ecx, &edx) && eax >= 0x80000004) {
        __get_cpuid(0x80000002, &brand_regs[0], &brand_regs[1], &brand_regs[2], &brand_regs[3]);
        __get_cpuid(0x80000003, &brand_regs[4], &brand_regs[5], &brand_regs[6], &brand_regs[7]);
        __get_cpuid(0x80000004, &brand_regs[8], &brand_regs[9], &brand_regs[10], &brand_regs[11]);
        memcpy(s_brand, brand_regs, sizeof(brand_regs));
        s_brand[sizeof(s_brand) - 1] = '\0';
    } else {
        strncpy(s_brand, "Generic x86 CPU", sizeof(s_brand) - 1);
    }
#elif defined(__EMSCRIPTEN__)
    strncpy(s_brand, "WebAssembly Runtime", sizeof(s_brand) - 1);
#else
    strncpy(s_brand, "Generic Host CPU", sizeof(s_brand) - 1);
#endif

    probe_topology();
    s_features = feats;
    atomic_store(&s_probed, true);
}

uint32_t rcre_cpu_get_features(void) {
    if (!atomic_load(&s_probed)) {
        probe_cpu();
    }
    return s_features;
}

const char* rcre_cpu_get_brand(void) {
    if (!atomic_load(&s_probed)) {
        probe_cpu();
    }
    return s_brand;
}

RCRE_CpuTopology rcre_cpu_get_topology(void) {
    if (!atomic_load(&s_probed)) {
        probe_cpu();
    }
    return s_topology;
}

int rcre_cpu_get_memory_pressure(void) {
#if defined(__APPLE__)
    /* XNU memorystatus levels: 1 = NORMAL, 2 = WARN, 4 = CRITICAL */
    int level = 1;
    size_t sz = sizeof(level);
    if (sysctlbyname("kern.memorystatus_vm_pressure_level", &level, &sz, nullptr, 0) == 0) {
        if (level >= 4) return 2;
        if (level >= 2) return 1;
    }
    return 0;
#elif defined(__linux__)
    /* Check Linux PSI (/proc/pressure/memory) first */
    FILE* psi = fopen("/proc/pressure/memory", "r");
    if (psi) {
        char line[128];
        double avg10 = 0.0;
        while (fgets(line, sizeof(line), psi)) {
            if (strncmp(line, "full ", 5) == 0 && sscanf(line, "full avg10=%lf", &avg10) == 1) {
                if (avg10 >= 20.0) { fclose(psi); return 2; }
                if (avg10 >= 5.0)  { fclose(psi); return 1; }
            }
        }
        fclose(psi);
    }
    /* Fallback to MemAvailable / MemTotal ratio in /proc/meminfo */
    FILE* mi = fopen("/proc/meminfo", "r");
    if (mi) {
        char key[64];
        unsigned long long val = 0;
        unsigned long long mem_total = 0, mem_avail = 0;
        char unit[32];
        while (fscanf(mi, "%63s %llu %31s", key, &val, unit) >= 2) {
            if (strcmp(key, "MemTotal:") == 0) mem_total = val;
            else if (strcmp(key, "MemAvailable:") == 0) mem_avail = val;
            if (mem_total > 0 && mem_avail > 0) break;
        }
        fclose(mi);
        if (mem_total > 0 && mem_avail > 0) {
            if (mem_avail * 25ULL < mem_total) return 2; /* < 4% free */
            if (mem_avail * 10ULL < mem_total) return 1; /* < 10% free */
        }
    }
    return 0;
#else
    return 0;
#endif
}

